// node --test: the AppDelegate transform of withNoUrlCache (runs in `npm test`).

const assert = require('node:assert/strict');
const { describe, it } = require('node:test');

const withNoUrlCache = require('./withNoUrlCache');

const { addNoUrlCache, NO_URL_CACHE_LINES } = withNoUrlCache;

// AppDelegate.swift as generated by the Expo SDK 58 template (abridged, the launch method verbatim).
const TEMPLATE = `internal import Expo
import React

@main
class AppDelegate: ExpoAppDelegate, ExpoReactNativeFactoryProvider {
  public override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil
  ) -> Bool {
    let delegate = ReactNativeDelegate()
    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }
}
`;

const count = (src, needle) => src.split(needle).length - 1;

describe('addNoUrlCache', () => {
  it('puts the cache lines first in didFinishLaunchingWithOptions, before React Native starts', () => {
    const out = addNoUrlCache(TEMPLATE);
    for (const line of NO_URL_CACHE_LINES) assert.equal(count(out, line), 1);
    assert.ok(out.indexOf(NO_URL_CACHE_LINES[1]) < out.indexOf('let delegate'));
    assert.match(out, /-> Bool \{\n {4}\/\/ statement-import:.*\n {4}URLCache\.shared\.remove/);
  });

  it('is idempotent: a second prebuild run does not duplicate the lines', () => {
    const once = addNoUrlCache(TEMPLATE);
    assert.equal(addNoUrlCache(once), once);
  });

  it('fails loudly when there is no launch method to anchor to', () => {
    assert.throws(() => addNoUrlCache('class AppDelegate {}\n'));
  });
});

describe('withNoUrlCache (mod wiring)', () => {
  const run = async (language, contents) => {
    const config = withNoUrlCache({ name: 'test', slug: 'test' });
    return config.mods.ios.appDelegate({
      name: 'test',
      slug: 'test',
      modResults: { path: '/x/AppDelegate.swift', language, contents },
      modRequest: { platform: 'ios', modName: 'appDelegate', projectRoot: '/x' },
      modRawConfig: { name: 'test', slug: 'test' },
    });
  };

  it('patches the Swift AppDelegate through withAppDelegate', async () => {
    const result = await run('swift', TEMPLATE);
    assert.equal(count(result.modResults.contents, NO_URL_CACHE_LINES[1]), 1);
  });

  it('refuses an Objective-C AppDelegate', async () => {
    await assert.rejects(run('objcpp', '@implementation AppDelegate\n@end\n'));
  });
});
